/**
 * Calculate moment of inertia based on mass and collision shape.
 *
 * Uses simplified scalar approximation (average of principal moments)
 * for performance. Formulas:
 * - Sphere: I = 0.4 × m × r²
 * - Capsule/Cylinder: I = (1/12) × m × (3r² + h²)
 * - Box: I = (1/12) × m × (w² + h² + d²) / 3
 *
 * @param {number} mass - Body mass (kg)
 * @param {number} collisionType - BodyCollisionType enum value
 * @param {THREE.BufferGeometry} geometry - Body geometry (for bounds)
 * @returns {number} Scalar moment of inertia (kg·m²)
 *
 * @example
 * ```js
 * import { calculateMomentOfInertia, BodyCollisionType } from '@three-blocks/pro';
 *
 * const inertia = calculateMomentOfInertia(1.0, BodyCollisionType.SPHERE, sphereGeometry);
 * console.log('Inertia:', inertia);
 * ```
 */
export function calculateMomentOfInertia(mass: number, collisionType: number, geometry: THREE.BufferGeometry): number;
/**
 * Calculate moment of inertia for a sphere.
 *
 * @param {number} mass - Body mass
 * @param {number} radius - Sphere radius
 * @returns {number} Moment of inertia
 */
export function sphereInertia(mass: number, radius: number): number;
/**
 * Calculate moment of inertia for a cylinder/capsule.
 *
 * @param {number} mass - Body mass
 * @param {number} radius - Cylinder radius
 * @param {number} height - Cylinder height
 * @returns {number} Moment of inertia (averaged)
 */
export function cylinderInertia(mass: number, radius: number, height: number): number;
/**
 * Calculate moment of inertia for a box.
 *
 * @param {number} mass - Body mass
 * @param {number} width - Box width
 * @param {number} height - Box height
 * @param {number} depth - Box depth
 * @returns {number} Moment of inertia (averaged of principal axes)
 */
export function boxInertia(mass: number, width: number, height: number, depth: number): number;
export default calculateMomentOfInertia;
